export function getCuratedHoroscope(
  sign: string,
  category: 'general' | 'love' | 'career' | 'wellness' | 'birthday',
  seedIndex: number = 0
): string {
  const cleanSign = sign.toLowerCase().split(' ')[0].trim();
  const signData = ASTRO_HOROSCOPE_DATASET[cleanSign] || ASTRO_HOROSCOPE_DATASET['aries'];
  const list = signData[category] || signData['general'] || [];
  if (list.length === 0) return '';
  const idx = Math.abs(seedIndex) % list.length;
  return list[idx];
}
